module QiskitJulia

using Libdl

const libqiskit = Ref{Ptr{Nothing}}()

function __init__()
    try
        libpath = joinpath(dirname(@__DIR__), "deps", "deps.jl")
        if isfile(libpath)
            include(libpath)
        end
        if libqiskit[] == C_NULL
            libqiskit[] = dlopen("libqiskit")
        end
    catch
        error("Could not load libqiskit. Please run Pkg.build(\"QiskitJulia\")")
    end
end

abstract type AbstractInstruction end

struct CircuitInstruction <: AbstractInstruction
    name::String
    qubits::Vector{Int32}
    clbits::Vector{Int32}
    params::Vector{Float64}
end

mutable struct QuantumCircuit
    ptr::Ptr{Cvoid}
    offset::Int
    function QuantumCircuit(num_qubits::Integer = 0, num_clbits::Integer = 0; offset::Int = 1)
        num_qubits >= 0 || throw(ArgumentError("Number of qubits must be non-negative."))
        num_clbits >= 0 || throw(ArgumentError("Number of clbits must be non-negative."))
        ptr = ccall((:qk_circuit_new, libqiskit[]), Ptr{Cvoid}, (UInt32, UInt32), num_qubits, num_clbits)
        qc = new(ptr, offset)
        finalizer(qc) do obj
            if obj.ptr != C_NULL
                ccall((:qk_circuit_free, libqiskit[]), Cvoid, (Ptr{Cvoid},), obj.ptr)
                obj.ptr = C_NULL
            end
        end
        qc
    end
end

function Base.copy(qc::QuantumCircuit)
    ptr = ccall((:qk_circuit_copy, libqiskit[]), Ptr{Cvoid}, (Ptr{Cvoid},), qc.ptr)
    new_qc = QuantumCircuit(0, 0; offset=qc.offset)
    new_qc.ptr = ptr
    return new_qc
end

function num_qubits(qc::QuantumCircuit)
    return ccall((:qk_circuit_num_qubits, libqiskit[]), Int32, (Ptr{Cvoid},), qc.ptr)
end

function num_clbits(qc::QuantumCircuit)
    return ccall((:qk_circuit_num_clbits, libqiskit[]), Int32, (Ptr{Cvoid},), qc.ptr)
end

function num_instructions(qc::QuantumCircuit)
    return ccall((:qk_circuit_num_instructions, libqiskit[]), Int32, (Ptr{Cvoid},), qc.ptr)
end

function get_instruction(qc::QuantumCircuit, index::Integer)
    name_ptr = ccall((:qk_circuit_get_instruction_name, libqiskit[]), Ptr{Cchar}, (Ptr{Cvoid}, Int32), qc.ptr, index - qc.offset)
    name = unsafe_string(name_ptr)

    qubits_len = ccall((:qk_circuit_get_instruction_qubits_len, libqiskit[]), Int32, (Ptr{Cvoid}, Int32), qc.ptr, index - qc.offset)
    qubits = Vector{Int32}(undef, qubits_len)
    ccall((:qk_circuit_get_instruction_qubits, libqiskit[]), Cvoid, (Ptr{Cvoid}, Int32, Ptr{Int32}), qc.ptr, index - qc.offset, qubits)

    clbits_len = ccall((:qk_circuit_get_instruction_clbits_len, libqiskit[]), Int32, (Ptr{Cvoid}, Int32), qc.ptr, index - qc.offset)
    clbits = Vector{Int32}(undef, clbits_len)
    ccall((:qk_circuit_get_instruction_clbits, libqiskit[]), Cvoid, (Ptr{Cvoid}, Int32, Ptr{Int32}), qc.ptr, index - qc.offset, clbits)

    params_len = ccall((:qk_circuit_get_instruction_params_len, libqiskit[]), Int32, (Ptr{Cvoid}, Int32), qc.ptr, index - qc.offset)
    params = Vector{Float64}(undef, params_len)
    ccall((:qk_circuit_get_instruction_params, libqiskit[]), Cvoid, (Ptr{Cvoid}, Int32, Ptr{Float64}), qc.ptr, index - qc.offset, params)

    return CircuitInstruction(name, qubits, clbits, params)
end

struct GateClosure
    qc::QuantumCircuit
    gate_name::String
    num_qubits::Int32
    num_params::Int32
end

function (gc::GateClosure)(args...)
    if length(args) != gc.num_qubits + gc.num_params
        throw(ArgumentError("Unexpected number of arguments for gate"))
    end
    params = collect(Float64, args[1:gc.num_params])
    qubits = collect(Int32, args[gc.num_params+1:end])
    ccall((:qk_circuit_gate, libqiskit[]), Cvoid, (Ptr{Cvoid}, Ptr{Cchar}, Ptr{Int32}, Int32, Ptr{Float64}, Int32), 
          gc.qc.ptr, gc.gate_name, qubits, length(qubits), params, length(params))
end

struct ResetInstructionClosure
    qc::QuantumCircuit
end

function (cl::ResetInstructionClosure)(qubit::Integer)
    ccall((:qk_circuit_reset, libqiskit[]), Cvoid, (Ptr{Cvoid}, Int32), cl.qc.ptr, qubit - cl.qc.offset)
end

struct MeasureInstructionClosure
    qc::QuantumCircuit
end

function (cl::MeasureInstructionClosure)(qubit::Integer, clbit::Integer)
    ccall((:qk_circuit_measure, libqiskit[]), Cvoid, (Ptr{Cvoid}, Int32, Int32), cl.qc.ptr, qubit - cl.qc.offset, clbit - cl.qc.offset)
end

struct BarrierInstructionClosure
    qc::QuantumCircuit
end

function (cl::BarrierInstructionClosure)(qubits::Integer...)
    qc = cl.qc
    if isempty(qubits)
        qubits_vector = collect(Int32, qc.offset:qc.num_qubits+qc.offset-1)
    else
        qubits_vector = collect(Int32, qubits)
    end
    ccall((:qk_circuit_barrier, libqiskit[]), Cvoid, (Ptr{Cvoid}, Ptr{Int32}, Int32), qc.ptr, qubits_vector, length(qubits_vector))
end

struct UnitaryInstructionClosure
    qc::QuantumCircuit
end

function (cl::UnitaryInstructionClosure)(matrix::AbstractMatrix{<:Number}, qubits::AbstractVector{<:Integer})
    matrix_flat = collect(Float64, vec(matrix))
    qubits_int = collect(Int32, qubits)
    ccall((:qk_circuit_unitary, libqiskit[]), Cvoid, (Ptr{Cvoid}, Ptr{Float64}, Int32, Ptr{Int32}, Int32), 
          cl.qc.ptr, matrix_flat, length(matrix_flat), qubits_int, length(qubits_int))
end

struct QuantumCircuitData <: AbstractVector{CircuitInstruction}
    circuit::QuantumCircuit
end

Base.IndexStyle(::Type{QuantumCircuitData}) = IndexLinear()
Base.size(qcdata::QuantumCircuitData) = (qcdata.circuit.num_instructions,)
Base.firstindex(qcdata::QuantumCircuitData) = qcdata.circuit.offset
Base.lastindex(qcdata::QuantumCircuitData) = firstindex(qcdata) + qcdata.circuit.num_instructions - 1

function Base.getindex(qcdata::QuantumCircuitData, i::Integer)
    @boundscheck checkbounds(qcdata, i - qcdata.circuit.offset + 1)
    return get_instruction(qcdata.circuit, i)
end

function Base.iterate(qcdata::QuantumCircuitData)
    if isempty(qcdata)
        return nothing
    else
        i = firstindex(qcdata)
        return (qcdata[i], i + 1)
    end
end

function Base.iterate(qcdata::QuantumCircuitData, state)
    qc = qcdata.circuit
    if state >= qc.num_instructions + qc.offset
        return nothing
    else
        return (qcdata[state], state + 1)
    end
end

function Base.propertynames(obj::QuantumCircuit; private::Bool = false)
    return (:data, :num_qubits, :num_clbits, :num_instructions, :reset, :measure, :barrier, :unitary, 
            :h, :id, :x, :y, :z, :p, :r, :rx, :ry, :rz, :s, :sdg, :sx, :sxdg, :t, :tdg, :u, 
            :ch, :cx, :cy, :cz, :dcx, :ecr, :swap, :iswap, :cp, :crx, :cry, :crz, :cs, :csdg, :csx, :cu, 
            :rxx, :ryy, :rzz, :rzx, :ccx, :ccz, :cswap, :rccx, :rcccx)
end

function Base.getproperty(qc::QuantumCircuit, sym::Symbol)
    if sym === :data
        return QuantumCircuitData(qc)
    elseif sym === :num_qubits
        return num_qubits(qc)
    elseif sym === :num_clbits
        return num_clbits(qc)
    elseif sym === :num_instructions
        return num_instructions(qc)
    elseif sym === :reset
        return ResetInstructionClosure(qc)
    elseif sym === :measure
        return MeasureInstructionClosure(qc)
    elseif sym === :barrier
        return BarrierInstructionClosure(qc)
    elseif sym === :unitary
        return UnitaryInstructionClosure(qc)
    elseif sym === :h
        return GateClosure(qc, "h", 1, 0)
    elseif sym === :id
        return GateClosure(qc, "id", 1, 0)
    elseif sym === :x
        return GateClosure(qc, "x", 1, 0)
    elseif sym === :y
        return GateClosure(qc, "y", 1, 0)
    elseif sym === :z
        return GateClosure(qc, "z", 1, 0)
    elseif sym === :p
        return GateClosure(qc, "p", 1, 1)
    elseif sym === :r
        return GateClosure(qc, "r", 1, 2)
    elseif sym === :rx
        return GateClosure(qc, "rx", 1, 1)
    elseif sym === :ry
        return GateClosure(qc, "ry", 1, 1)
    elseif sym === :rz
        return GateClosure(qc, "rz", 1, 1)
    elseif sym === :s
        return GateClosure(qc, "s", 1, 0)
    elseif sym === :sdg
        return GateClosure(qc, "sdg", 1, 0)
    elseif sym === :sx
        return GateClosure(qc, "sx", 1, 0)
    elseif sym === :sxdg
        return GateClosure(qc, "sxdg", 1, 0)
    elseif sym === :t
        return GateClosure(qc, "t", 1, 0)
    elseif sym === :tdg
        return GateClosure(qc, "tdg", 1, 0)
    elseif sym === :u
        return GateClosure(qc, "u", 1, 3)
    elseif sym === :ch
        return GateClosure(qc, "ch", 2, 0)
    elseif sym === :cx
        return GateClosure(qc, "cx", 2, 0)
    elseif sym === :cy
        return GateClosure(qc, "cy", 2, 0)
    elseif sym === :cz
        return GateClosure(qc, "cz", 2, 0)
    elseif sym === :dcx
        return GateClosure(qc, "dcx", 2, 0)
    elseif sym === :ecr
        return GateClosure(qc, "ecr", 2, 0)
    elseif sym === :swap
        return GateClosure(qc, "swap", 2, 0)
    elseif sym === :iswap
        return GateClosure(qc, "iswap", 2, 0)
    elseif sym === :cp
        return GateClosure(qc, "cp", 2, 1)
    elseif sym === :crx
        return GateClosure(qc, "crx", 2, 1)
    elseif sym === :cry
        return GateClosure(qc, "cry", 2, 1)
    elseif sym === :crz
        return GateClosure(qc, "crz", 2, 1)
    elseif sym === :cs
        return GateClosure(qc, "cs", 2, 0)
    elseif sym === :csdg
        return GateClosure(qc, "csdg", 2, 0)
    elseif sym === :csx
        return GateClosure(qc, "csx", 2, 0)
    elseif sym === :cu
        return GateClosure(qc, "cu", 2, 3)
    elseif sym === :rxx
        return GateClosure(qc, "rxx", 2, 1)
    elseif sym === :ryy
        return GateClosure(qc, "ryy", 2, 1)
    elseif sym === :rzz
        return GateClosure(qc, "rzz", 2, 1)
    elseif sym === :rzx
        return GateClosure(qc, "rzx", 2, 1)
    elseif sym === :ccx
        return GateClosure(qc, "ccx", 3, 0)
    elseif sym === :ccz
        return GateClosure(qc, "ccz", 3, 0)
    elseif sym === :cswap
        return GateClosure(qc, "cswap", 3, 0)
    elseif sym === :rccx
        return GateClosure(qc, "rccx", 3, 0)
    elseif sym === :rcccx
        return GateClosure(qc, "rcccx", 4, 0)
    else
        return getfield(qc, sym)
    end
end

function count_ops(qc::QuantumCircuit)
    ops_len = ccall((:qk_circuit_count_ops_len, libqiskit[]), Int32, (Ptr{Cvoid},), qc.ptr)
    ops_names = Vector{Ptr{Cchar}}(undef, ops_len)
    ops_counts = Vector{Int32}(undef, ops_len)
    ccall((:qk_circuit_count_ops, libqiskit[]), Cvoid, (Ptr{Cvoid}, Ptr{Ptr{Cchar}}, Ptr{Int32}), 
          qc.ptr, ops_names, ops_counts)

    result = Dict{String, Int}()
    for i in 1:ops_len
        result[unsafe_string(ops_names[i])] = ops_counts[i]
    end
    return result
end

end
